'use strict';
/* One file with the whole corpus in it, so a browser can match concepts.
 *
 * `knowledge()` in lib/analyze.js walks 137 concept files and reads the
 * warnings index off disk. Study Board has no filesystem and cannot fetch 138
 * files to draw one card, so this writes what that walk produces — the SAME
 * objects, not a summary of them — into `dist/education-bundle.json`, which the
 * page hands back through `setKnowledge()`.
 *
 * NOTHING IS TRIMMED, and that is the whole design of this tool. A bundle
 * carrying a subset of each record would be smaller and would silently change
 * what matches: `matchers.js` reads `recognition`, `analyze.js` reads
 * `explanations` and `terminology.avoid`, `cautionsFor()` reads the warnings
 * index, and a field dropped because it looked unused is a false negative
 * nobody would see. Shipping everything makes the browser's answer identical to
 * Node's by construction rather than by hope. `tests/test_bundle.js` is what
 * would license a trim later; until it exists and passes over the shipped
 * corpus, a trim is guessing.
 *
 * Generated, never hand-edited — rebuild it rather than patch it. `--check`
 * rebuilds in memory and compares, so a stale bundle fails the suite instead of
 * reaching a player.
 *
 *     node education/tools/build_bundle.js            # write it
 *     node education/tools/build_bundle.js --check     # fail if stale
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, 'dist', 'education-bundle.json');

/* The same walk `knowledge()` makes, in the same order, so the two cannot
 * disagree about what the corpus is. Sorted, because a bundle whose key order
 * depends on readdir order produces a spurious diff on another machine. */
function build() {
  const concepts = {};
  const cdir = path.join(ROOT, 'concepts');
  for (const d of fs.readdirSync(cdir).sort()) {
    const sub = path.join(cdir, d);
    if (!fs.statSync(sub).isDirectory()) continue;
    for (const fn of fs.readdirSync(sub).sort()) {
      if (!fn.endsWith('.json')) continue;
      const c = JSON.parse(fs.readFileSync(path.join(sub, fn), 'utf8'));
      concepts[c.id] = c;
    }
  }
  let warnings = { entries: [] };
  const wp = path.join(ROOT, 'state', 'warnings_index.json');
  if (fs.existsSync(wp)) warnings = JSON.parse(fs.readFileSync(wp, 'utf8'));

  const ids = Object.keys(concepts).sort();
  const ordered = {};
  for (const id of ids) ordered[id] = concepts[id];
  return {
    format: 1,
    note: 'Generated by education/tools/build_bundle.js. Do not edit. ' +
          'Handed to lib/analyze.js setKnowledge() by blind-chess.html.',
    concepts: ordered,
    warnings,
  };
}

/* The bytes, without a timestamp in them.
 *
 * A `built` field was the obvious thing to add and is the wrong thing: it makes
 * every rebuild a diff, so `--check` would fail on a clean tree and the staleness
 * signal would be noise. The content is the version. */
function serialise(b) {
  return JSON.stringify(b) + '\n';
}

function main() {
  const check = process.argv.includes('--check');
  const text = serialise(build());

  if (check) {
    if (!fs.existsSync(OUT)) {
      console.error('BUNDLE MISSING — run: node education/tools/build_bundle.js');
      return 1;
    }
    const have = fs.readFileSync(OUT, 'utf8');
    if (have !== text) {
      console.error(`BUNDLE STALE — ${OUT} does not match the concepts on disk.\n` +
                    `  have ${have.length} bytes, corpus produces ${text.length}\n` +
                    '  run: node education/tools/build_bundle.js');
      return 1;
    }
    const n = Object.keys(JSON.parse(have).concepts).length;
    console.log(`bundle up to date — ${n} concepts, ${have.length} bytes`);
    return 0;
  }

  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, text);
  const b = JSON.parse(text);
  console.log(`wrote ${path.relative(path.join(ROOT, '..'), OUT)} — ` +
              `${Object.keys(b.concepts).length} concepts, ` +
              `${(b.warnings.entries || []).length} warnings, ${text.length} bytes`);
  console.log('remember to bump EDU_VERSION in blind-chess.html, or a week of cache ' +
              'will serve the old corpus');
  return 0;
}

if (require.main === module) process.exit(main());
module.exports = { build, serialise, OUT };
